// CommandError describes a failed command execution. It implements `error` via
// its Error method, so a `Failed` arm can be returned directly where an
// `error` is expected (e.g. `return r.Error`). Stdout and Stderr carry both
// streams even on failure, matching Capture's needs.
type CommandError struct {
	Name      string
	Args      []string
	ExitCode  int
	Stdout    []byte
	Stderr    []byte
	Cause     error
	Truncated bool
}

// Error renders the failure as a human-readable summary.
func (e CommandError) Error() string {
	msg := e.Name
	if len(e.Args) != 0 {
		msg = msg + " " + kukistring.Join(e.Args, " ")
	}
	if e.Truncated {
		if e.Cause != nil && kukistring.Contains(e.Cause.Error(), "stderr limit") {
			msg += ": stderr limit exceeded"
		} else {
			msg += ": output limit exceeded"
		}
	} else {
		msg += fmt.Sprintf(": exit status %v", e.ExitCode)
	}
	if len(e.Stderr) != 0 {
		msg += fmt.Sprintf(": %v", string(e.Stderr))
	}
	return msg
}

