// New creates a new Command builder. Chain with .Flag / .FlagIf / .Dir /
// .Env / .Timeout, then terminate with .Output() or .Execute().
// Example:
//
//	out := shell.New("aws", "s3api", "create-bucket")
//	    |> .Flag("--bucket", bucket)
//	    |> .Flag("--region", region)
//	    |> .Output() onerr
//	        return error "could not create bucket: {error}"
func New(name string, args ...string) Command {
	ownedArgs := append([]string{}, args...)
	return Command{name: name, args: ownedArgs, dir: "", timeout: 0, env: map[string]string{}, stdin: []byte{}, outputLimit: 0, stderrLimit: 0}
}

// Fatal prints a message to stderr and exits with code 1. Use in a pipe's
// onerr to stop a script on the first failing step, e.g.
//
//	shell.Output("aws", "sts", "get-caller-identity") onerr shell.Fatal("{error}")
func Fatal(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	os.Exit(1)
}

