// boundedWriter is an io.Writer that limits captured output.
// When limit is reached, it invokes onExceed once and marks exceeded = true.
type boundedWriter struct {
	buf      *bytes.Buffer
	limit    int
	written  int
	onExceed func()
	exceeded bool
}

func (w *boundedWriter) Write(p []byte) (int, error) {
	if w.limit <= 0 {
		return w.buf.Write(p)
	}
	if w.written >= w.limit {
		if !w.exceeded {
			w.exceeded = true
			if w.onExceed != nil {
				w.onExceed()
			}
		}
		return len(p), nil
	}
	remaining := w.limit - w.written
	if len(p) <= remaining {
		n, err := w.buf.Write(p)
		w.written += n
		return n, err
	}
	n, err := w.buf.Write(p[:remaining])
	w.written += n
	w.exceeded = true
	if w.onExceed != nil {
		w.onExceed()
	}
	if err != nil {
		return n, err
	}
	return len(p), nil
}

func prepareCmd(cmd Command, ctx context.Context) *exec.Cmd {
	execCmd := exec.CommandContext(ctx, cmd.name, cmd.args...)
	if cmd.dir != "" {
		execCmd.Dir = cmd.dir
	}
	if len(cmd.env) != 0 {
		env := os.Environ()
		for key, value := range cmd.env {
			env = append(env, fmt.Sprintf("%v=%v", key, value))
		}
		execCmd.Env = env
	}
	if len(cmd.stdin) != 0 {
		execCmd.Stdin = bytes.NewReader(cmd.stdin)
	}
	return execCmd
}

// Execute runs the command and returns a Result. Prefer .Output() when you
// just want stdout + error.
// Note: Execute does not carry a kuki:security "shell" directive because builder methods like .Flag() bypass shell delimiters, preventing shell injections.
// Example: result := cmd |> .Execute()
func (cmd Command) Execute() Result {
	h := ctxpkg.Background()
	if cmd.timeout > 0 {
		h = ctxpkg.WithTimeout(h, cmd.timeout)
	}
	hCancel := ctxpkg.WithCancel(h)
	defer hCancel.Cancel()
	defer h.Cancel()
	execCmd := prepareCmd(cmd, hCancel.Ctx)
	stdoutBuf := bytes.Buffer{}
	stderrBuf := bytes.Buffer{}
	stdoutBW := &boundedWriter{buf: &stdoutBuf, limit: cmd.outputLimit, written: 0, onExceed: func() { hCancel.Cancel() }, exceeded: false}
	stderrBW := &boundedWriter{buf: &stderrBuf, limit: cmd.stderrLimit, written: 0, onExceed: func() { hCancel.Cancel() }, exceeded: false}
	if cmd.outputLimit > 0 {
		execCmd.Stdout = stdoutBW
	} else {
		execCmd.Stdout = &stdoutBuf
	}
	if cmd.stderrLimit > 0 {
		execCmd.Stderr = stderrBW
	} else {
		execCmd.Stderr = &stderrBuf
	}
	err := execCmd.Run()
	stdout := stdoutBuf.Bytes()
	stderr := stderrBuf.Bytes()
	if stdoutBW.exceeded {
		return Failed{Error: CommandError{Name: cmd.name, Args: cmd.args, ExitCode: getExitCode(err), Stdout: stdout, Stderr: stderr, Cause: fmt.Errorf("output limit of %v bytes exceeded", cmd.outputLimit), Truncated: true}}
	}
	if stderrBW.exceeded {
		return Failed{Error: CommandError{Name: cmd.name, Args: cmd.args, ExitCode: getExitCode(err), Stdout: stdout, Stderr: stderr, Cause: fmt.Errorf("stderr limit of %v bytes exceeded", cmd.stderrLimit), Truncated: true}}
	}
	if err == nil {
		return Succeeded{Stdout: stdout, Stderr: stderr}
	}
	return Failed{Error: CommandError{Name: cmd.name, Args: cmd.args, ExitCode: getExitCode(err), Stdout: stdout, Stderr: stderr, Cause: err, Truncated: false}}
}

// Output runs the command and returns stdout as a string, or an error
// wrapping stderr on failure. The most common terminal for a builder chain.
// Example:
//
//	out := shell.New("git", "status") |> .Output() onerr return
func (cmd Command) Output() (string, error) {
	result := cmd.Execute()
	return Require(result)
}

// Capture runs the command and returns (stdout, stderr, error).
// Unlike Output, Capture returns both streams even on success — useful when
// you need stderr for logging or diagnostics alongside stdout.
// Example:
//
//	out, errOut, err := shell.New("go", "build", "./...") |> .Capture() onerr return
func (cmd Command) Capture() (string, string, error) {
	result := cmd.Execute()
	switch r := result.(type) {
	case Succeeded:
		return string(r.Stdout), string(r.Stderr), nil
	case Failed:
		if r.Error.Truncated {
			return string(r.Error.Stdout), string(r.Error.Stderr), r.Error.Cause
		}
		return string(r.Error.Stdout), string(r.Error.Stderr), fmt.Errorf("%v", string(r.Error.Stderr))
	default:
		panic("unreachable")
	}
}

// Check runs the command, discards output, and returns nil on success or an
// error wrapping stderr on failure. Useful for commands where only success
// matters (e.g. "tofu init").
// Example:
//
//	cmd |> .Check() onerr return error "init failed: {error}"
func (cmd Command) Check() error {
	_, _, err := cmd.Capture()
	return err
}

// Stream runs the command and streams its stdout line-by-line to onLine.
// If outputLimit is set and exceeded, the process is terminated and an error is returned.
// Stderr is captured and included in the returned CommandError on failure.
// Example:
//
//	cmd |> .Stream((line: string) => print(line))
func (cmd Command) Stream(onLine func(string)) error {
	h := ctxpkg.Background()
	if cmd.timeout > 0 {
		h = ctxpkg.WithTimeout(h, cmd.timeout)
	}
	hCancel := ctxpkg.WithCancel(h)
	defer hCancel.Cancel()
	defer h.Cancel()
	execCmd := prepareCmd(cmd, hCancel.Ctx)
	stdoutPipe, err_2 := execCmd.StdoutPipe()
	if err_2 != nil {
		return err_2
	}
	stderrBuf := bytes.Buffer{}
	stderrBW := &boundedWriter{buf: &stderrBuf, limit: cmd.stderrLimit, written: 0, onExceed: func() { hCancel.Cancel() }, exceeded: false}
	if cmd.stderrLimit > 0 {
		execCmd.Stderr = stderrBW
	} else {
		execCmd.Stderr = &stderrBuf
	}
	err_3 := execCmd.Start()
	if err_3 != nil {
		return err_3
	}
	scanner := bufio.NewScanner(stdoutPipe)
	scanner.Buffer([]byte{}, 8*1024*1024)
	totalBytes := 0
	limitExceeded := false
	for scanner.Scan() {
		line := scanner.Text()
		if cmd.outputLimit > 0 {
			lineBytes := len(scanner.Bytes()) + 1
			if totalBytes+lineBytes > cmd.outputLimit {
				limitExceeded = true
				hCancel.Cancel()
				break
			}
			totalBytes += lineBytes
		}
		if onLine != nil {
			onLine(line)
		}
	}
	waitErr := execCmd.Wait()
	if limitExceeded {
		return CommandError{Name: cmd.name, Args: cmd.args, ExitCode: getExitCode(waitErr), Stderr: stderrBuf.Bytes(), Truncated: true, Cause: fmt.Errorf("output limit of %v bytes exceeded", cmd.outputLimit)}
	}
	if stderrBW.exceeded {
		return CommandError{Name: cmd.name, Args: cmd.args, ExitCode: getExitCode(waitErr), Stderr: stderrBuf.Bytes(), Truncated: true, Cause: fmt.Errorf("stderr limit of %v bytes exceeded", cmd.stderrLimit)}
	}
	if waitErr != nil {
		return CommandError{Name: cmd.name, Args: cmd.args, ExitCode: getExitCode(waitErr), Stderr: stderrBuf.Bytes(), Cause: waitErr, Truncated: false}
	}
	return nil
}

// StreamCapture runs the command and streams both stdout and stderr line-by-line
// to concurrent callbacks in real time.
