// Lines returns an iterator yielding stdout line-by-line.
// If iteration stops early (e.g. `break`), the child process is terminated.
// Example:
//
//	for line in cmd |> .Lines()
//	    if line == "stop"
//	        break
func (cmd Command) Lines() iter.Seq[string] {
	return func(yield func(string) bool) {
		h := ctxpkg.Background()
		if cmd.timeout > 0 {
			h = ctxpkg.WithTimeout(h, cmd.timeout)
		}
		hCancel := ctxpkg.WithCancel(h)
		defer hCancel.Cancel()
		defer h.Cancel()
		execCmd := prepareCmd(cmd, hCancel.Ctx)
		stdoutPipe, err_7 := execCmd.StdoutPipe()
		if err_7 != nil {
			return
		}
		err_8 := execCmd.Start()
		if err_8 != nil {
			return
		}
		defer func() {
			_ = execCmd.Wait()
		}()
		scanner := bufio.NewScanner(stdoutPipe)
		scanner.Buffer([]byte{}, 8*1024*1024)
		totalBytes := 0
		for scanner.Scan() {
			line := scanner.Text()
			if cmd.outputLimit > 0 {
				lineBytes := len(scanner.Bytes()) + 1
				if totalBytes+lineBytes > cmd.outputLimit {
					hCancel.Cancel()
					return
				}
				totalBytes += lineBytes
			}
			if !yield(line) {
				hCancel.Cancel()
				return
			}
		}
	}
}

// getExitCode extracts the exit code from an error
func getExitCode(err error) int {
	if err == nil {
		return 0
	}
	code := func() int {
		switch exitErr := err.(type) {
		case *exec.ExitError:
			return exitErr.ExitCode()
		default:
			return 1
		}
	}()
	return code
}

// Success returns true if the command succeeded (exit code 0)
// Example: if result |> shell.Success() ...
func Success(result Result) bool {
	return cast.Is[Succeeded](result)
}

// Require returns stdout as a string or an error wrapping the failure when the
// command failed, making the happy path a single pipe chain.
// Example: out := shell.New("go", "test", "./...") |> .Execute() |> shell.Require() onerr return
func Require(result Result) (string, error) {
	switch r := result.(type) {
	case Succeeded:
		return string(r.Stdout), nil
	case Failed:
		return "", r.Error
	default:
		panic("unreachable")
	}
}

// Which checks if a command exists in the system PATH
// Returns true if the command is found, false otherwise
// Example: if shell.Which("git") ...
func Which(name string) bool {
	_, err := exec.LookPath(name)
	return err == nil
}

// IsInstalled reports whether name is found on PATH.
// English alias for Which — reads as a question.
// Example: if shell.IsInstalled("git") ...
func IsInstalled(name string) bool {
	_, err := exec.LookPath(name)
	return err == nil
}
